-- public.pieces_held(p_world uuid, p_uid uuid, p_relic text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.pieces_held(p_world uuid, p_uid uuid, p_relic text)
 RETURNS SETOF item
 LANGUAGE sql
 STABLE
AS $function$
  select distinct on (fragment_part(i.extra)) i.*
  from item i
  where i.world_id = p_world and i.holder = 'player' and i.holder_uid = p_uid
    and i.def = 'fragment' and fragment_relic(i.extra) = p_relic
  order by fragment_part(i.extra), i.dmg
$function$
